    46	void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
    47	{
    48	    struct driver_data *data;
    49	
    50	    if (chunk)
    51	        *chunk = NULL;
    52	    if (chunk_size)
    53	        *chunk_size = 0;
    54	
    55	    if (!chunk || !chunk_size || !reader) {
    56	        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
    57	        return;
    58	    }
    59	    data = reader->drv_data;
    60	    if (!data || !data->Data || data->Size < sizeof *chunk_size) {
    61	        sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
    62	        return;
    63	    }
    64	
    65	    data->Size -= sizeof *chunk_size;
    66	    *chunk_size = (uint16_t) *data->Data;
    67	    data->Data += sizeof *chunk_size;
    68	    *chunk = data->Data;
    69	
    70	    if (data->Size < *chunk_size) {
    71	        *chunk_size = data->Size;
    72	    }
    73	
    74	    sc_debug_hex(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL,
    75	        "Returning fuzzing chunk", *chunk, *chunk_size);
    76	}
