    78	static int fuzz_reader_release(sc_reader_t *reader)
    79	{
    80	    if (reader) {
    81	        free(reader->drv_data);
    82	        reader->drv_data = NULL;
    83	    }
    84	
    85	    return SC_SUCCESS;
    86	}
