   111	static int fuzz_reader_transmit(sc_reader_t *reader, sc_apdu_t *apdu)
   112	{
   113	    const uint8_t *chunk;
   114	    uint16_t chunk_size;
   115	
   116	    fuzz_get_chunk(reader, &chunk, &chunk_size);
   117	
   118	    if (chunk_size >= 2) {
   119	        /* set the SW1 and SW2 status bytes (the last two bytes of
   120	         * the response */
   121	        apdu->sw1 = (unsigned int)chunk[chunk_size - 2];
   122	        apdu->sw2 = (unsigned int)chunk[chunk_size - 1];
   123	        chunk_size -= 2;
   124	        /* set output length and copy the returned data if necessary */
   125	        if (chunk_size <= apdu->resplen)
   126	            apdu->resplen = chunk_size;
   127	
   128	        if (apdu->resplen != 0)
   129	            memcpy(apdu->resp, chunk, apdu->resplen);
   130	    } else {
   131	        apdu->sw1 = 0x6D;
   132	        apdu->sw2 = 0x00;
   133	        apdu->resplen = 0;
   134	    }
   135	
   136	    return SC_SUCCESS;
   137	}
