   148	void fuzz_add_reader(struct sc_context *ctx, const uint8_t *Data, size_t Size)
   149	{
   150	    sc_reader_t *reader;
   151	    struct driver_data *data;
   152	    char name[64] = {0};
   153	
   154	    if (!(reader = calloc(1, sizeof(*reader)))
   155	            || !(data = (calloc(1, sizeof(*data))))) {
   156	        free(reader);
   157	        return;
   158	    }
   159	
   160	    data->Data = Data;
   161	    data->Size = Size;
   162	
   163	    reader->driver = &fuzz_drv;
   164	    reader->ops = &fuzz_ops;
   165	    reader->drv_data = data;
   166	    snprintf(name, sizeof name - 1, "%zu random byte%s reader (%p)",
   167	            Size, Size == 1 ? "" : "s", Data);
   168	    reader->name = strdup(name);
   169	
   170	    reader->ctx = ctx;
   171	    list_append(&ctx->readers, reader);
   172	}
