   174	int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
   175	{
   176	    struct sc_context *ctx = NULL;
   177	    struct sc_card *card = NULL;
   178	    struct sc_pkcs15_card *p15card = NULL;
   179	    struct sc_reader *reader;
   180	    struct sc_pkcs15_object *obj;
   181	
   182	    sc_establish_context(&ctx, "fuzz");
   183	    if (!ctx)
   184	        return 0;
   185	    /* copied from sc_release_context() */
   186	    while (list_size(&ctx->readers)) {
   187	        sc_reader_t *rdr = (sc_reader_t *) list_get_at(&ctx->readers, 0);
   188	        _sc_delete_reader(ctx, rdr);
   189	    }
   190	    if (ctx->reader_driver->ops->finish != NULL)
   191	        ctx->reader_driver->ops->finish(ctx);
   192	
   193	    ctx->reader_driver = sc_get_fuzz_driver();
   194	
   195	    fuzz_add_reader(ctx, Data, Size);
   196	
   197	    reader = sc_ctx_get_reader(ctx, 0);
   198	    sc_connect_card(reader, &card);
   199	    sc_pkcs15_bind(card, NULL, &p15card);
   200	
   201	    if (p15card) {
   202	        const uint8_t *in, *param;
   203	        uint16_t in_len, param_len;
   204	        fuzz_get_chunk(reader, &in, &in_len);
   205	        fuzz_get_chunk(reader, &param, &param_len);
   206	        for (obj = p15card->obj_list; obj != NULL; obj = obj->next) {
   207	            u8 buf[0xFFFF];
   208	            size_t i;
   209	
   210	            int decipher_flags[] = {SC_ALGORITHM_RSA_RAW,
   211	                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
   212	                SC_ALGORITHM_RSA_PAD_ISO9796};
   213	            for (i = 0; i < sizeof decipher_flags/sizeof *decipher_flags; i++) {
   214	                sc_pkcs15_decipher(p15card, obj, decipher_flags[i],
   215	                        in, in_len, buf, sizeof buf);
   216	            }
   217	
   218	            i = sizeof buf;
   219	            sc_pkcs15_derive(p15card, obj, 0,
   220	                    in, in_len, buf, &i);
   221	
   222	            int wrap_flags[] = {0, SC_ALGORITHM_AES_ECB, SC_ALGORITHM_AES_CBC_PAD,
   223	                SC_ALGORITHM_AES_CBC};
   224	            for (i = 0; i < sizeof wrap_flags/sizeof *wrap_flags; i++) {
   225	                struct sc_pkcs15_object target_key;
   226	                sc_pkcs15_unwrap(p15card, obj, &target_key, wrap_flags[i],
   227	                        in, in_len, param, param_len);
   228	                unsigned long l = sizeof buf;
   229	                sc_pkcs15_wrap(p15card, obj, &target_key, wrap_flags[i],
   230	                        buf, &l, in, in_len);
   231	            }
   232	
   233	            int signature_flags[] = {SC_ALGORITHM_RSA_RAW,
   234	                SC_ALGORITHM_RSA_PAD_PKCS1, SC_ALGORITHM_RSA_PAD_ANSI,
   235	                SC_ALGORITHM_RSA_PAD_ISO9796,
   236	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA1,
   237	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA256,
   238	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA384,
   239	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA512,
   240	                SC_ALGORITHM_RSA_PAD_PSS|SC_ALGORITHM_MGF1_SHA224,
   241	                SC_ALGORITHM_ECDSA_RAW, SC_ALGORITHM_ECDSA_HASH_SHA1,
   242	                SC_ALGORITHM_ECDSA_HASH_SHA224, SC_ALGORITHM_ECDSA_HASH_SHA256,
   243	                SC_ALGORITHM_ECDSA_HASH_SHA384, SC_ALGORITHM_ECDSA_HASH_SHA512,
   244	                SC_ALGORITHM_GOSTR3410_RAW, SC_ALGORITHM_GOSTR3410_HASH_GOSTR3411,
   245	                SC_ALGORITHM_GOSTR3410_HASHES,
   246	            };
   247	            for (i = 0; i < sizeof signature_flags/sizeof *signature_flags; i++) {
   248	                sc_pkcs15_compute_signature(p15card, obj, signature_flags[i],
   249	                        in, in_len, buf, sizeof buf);
   250	            }
   251	
   252	            sc_pkcs15_verify_pin(p15card, obj, in, in_len);
   253	            sc_pkcs15_change_pin(p15card, obj, in, in_len, param, param_len);
   254	            sc_pkcs15_unblock_pin(p15card, obj, in, in_len, param, param_len);
   255	            sc_pkcs15_get_pin_info(p15card, obj);
   256	        }
   257	        sc_pkcs15_card_free(p15card);
   258	    }
   259	
   260	    sc_disconnect_card(card);
   261	    sc_release_context(ctx);
   262	
   263	    return 0;
   264	}
